import React from 'react';
import { Input, PaginationBar, SearchInput, Stack, Table } from '@oods/components-react';
import '@oods/component-styles/css';

export interface PageProps {
  /** Array of currently applied filter values:
  - field: string (matches a filter descriptor field)
  - operator: "eq" | "in" | "range" | "gt" | "lt" | "between"
  - value: unknown (the selected filter value or values)
 */
  activeFilters?: Record<string, unknown>[];
  /** How many artifacts the run's index lists. */
  artifactCount: number;
  /** The authentication the manifest RECORDS. Shown as recorded, never inferred: Sprint 204 measured "none" on a capture that was authenticated, which is Stage1's to correct. */
  authType: string;
  /** Findings of critical impact. */
  criticalCount: number;
  /** Whether the run kept its evidence directory (evidence_retention.retained). */
  evidenceRetained?: boolean;
  /** Computed count of currently active filters. */
  filterCount: number;
  /** Array of available filter descriptors. Each entry defines a filterable dimension:
  - field: string (the schema field to filter on)
  - label: string (display label)
  - type: "select" | "multi-select" | "range" | "boolean" | "date-range"
  - options: array of { value, label } for select/multi-select types
 */
  filters?: Record<string, unknown>[];
  /** How many rule failures the run found across its pages (a11y rollup.violation_count). */
  findingCount: number;
  /** Findings of minor impact. */
  minorCount: number;
  /** The capture mode. Every run a run view reads is app; suite runs aggregate targets and carry no a11y report of their own. */
  mode: 'app' | 'suite';
  /** Findings of moderate impact. */
  moderateCount: number;
  /** Current page number (1-based). */
  page: number;
  /** How many pages the accessibility pass read. */
  pageCount: number;
  /** Number of items displayed per page. */
  pageSize: number;
  /** How many capture passes ran. */
  passCount: number;
  /** How many of those passes did not finish ok. */
  passesFailed: number;
  /** When they were obtained. */
  provenanceAt: string;
  /** Where in that record the values were read. */
  provenanceLocator?: string;
  /** How the values were obtained. */
  provenanceMethod: string;
  /** Which record there. */
  provenanceRecord: string;
  /** The system that produced the record. */
  provenanceSource: string;
  /** The capture's own id, a uuid Stage1 assigns; the directory name under out/stage1/<suite>/. */
  runId: string;
  /** Whether the search input is currently focused or has a non-empty query. */
  searchActive?: boolean;
  /** The current search query string entered by the user. */
  searchQuery?: string;
  /** Findings of serious impact. */
  seriousCount: number;
  /** What was captured, as the run names it (targets[0].name). Every run read carries exactly one target, so the subject is two fields here rather than an object of its own. */
  targetName: string;
  /** Where the capture started (targets[0].url). */
  targetUrl: string;
  /** Total number of items across all pages. Used to compute total page count. */
  totalItems?: number;
  /** Computed total number of pages (ceil(totalItems / pageSize)). */
  totalPages?: number;
  /** Findings whose impact the engine did not state. Its own bucket: never folded into minor. */
  unknownCount: number;
}

type InputProps = React.ComponentPropsWithoutRef<typeof Input>;
type PaginationBarProps = React.ComponentPropsWithoutRef<typeof PaginationBar>;
type SearchInputProps = React.ComponentPropsWithoutRef<typeof SearchInput>;
type StackProps = React.ComponentPropsWithoutRef<typeof Stack>;
type TableProps = React.ComponentPropsWithoutRef<typeof Table>;

export const GeneratedUI: React.FC<PageProps> = ({ activeFilters, artifactCount, authType, criticalCount, evidenceRetained, filterCount, filters, findingCount, minorCount, mode, moderateCount, page, pageCount, pageSize, passCount, passesFailed, provenanceAt, provenanceLocator, provenanceMethod, provenanceRecord, provenanceSource, runId, searchActive, searchQuery, seriousCount, targetName, targetUrl, totalItems, totalPages, unknownCount }) => {
  const [handleChange_artifact_countState, setHandleChange_artifact_countState] = React.useState<string>(String(artifactCount ?? ''));
  /* @oods-local-binding handleChange_artifact_count */ const handleChange_artifact_count = (event: React.ChangeEvent<HTMLInputElement>) => { setHandleChange_artifact_countState(event.currentTarget.value); };
  const [handleUpdate_searchQueryState, setHandleUpdate_searchQueryState] = React.useState<string>(String(searchQuery ?? ''));
  /* @oods-local-binding handleUpdate_searchQuery */ const handleUpdate_searchQuery = (value: string) => { setHandleUpdate_searchQueryState(value); };

  return (
    <main data-oods-shell="screen-list-9">
      <h1 data-oods-shell-heading="true">Run</h1>
      <Stack id="screen-list-9" data-oods-component="Stack" data-layout="stack" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--ref-space-cluster-default)' }}>
            <Stack id="list-toolbar-4" data-oods-component="Stack" data-layout="inline" style={{ display: 'flex', flexDirection: 'row', justifyContent: 'space-between', padding: 'var(--ref-space-inset-default)' }}>
                    <SearchInput id="slot-search-1" data-oods-component="SearchInput" label="Search Query" placeholder="Enter searchQuery" value={handleUpdate_searchQueryState} onUpdate={handleUpdate_searchQuery} />
                    <Input id="slot-filters-2" data-oods-component="Input" label="Artifact count" placeholder="Enter artifact count" required type="number" value={handleChange_artifact_countState} onChange={handleChange_artifact_count} />
                  </Stack>
            <Stack id="list-items-5" data-oods-component="Stack" data-layout="stack" style={{ display: 'flex', flexDirection: 'column', gap: 'var(--ref-space-cluster-tight)' }}>
                    <Table id="slot-items-6" data-oods-component="Table" />
                  </Stack>
            <Stack id="list-pagination-7" data-oods-component="Stack" data-layout="inline" style={{ display: 'flex', flexDirection: 'row', justifyContent: 'center', padding: 'var(--ref-space-inset-default)' }}>
                    <PaginationBar id="slot-pagination-8" data-oods-component="PaginationBar" />
                  </Stack>
          </Stack>
    </main>
  );
};

